414	     *
415	     * @param name to test
416	     * @return true if pet name is already in use
417	     */
418	    public Pet getPet(String name, boolean ignoreNew) {
419	        name = name.toLowerCase();
420	        for (Pet pet : getPetsInternal()) {
421	            if (!ignoreNew || !pet.isNew()) {
422	                String compName = pet.getName();
423	                compName = compName.toLowerCase();
424	                if (compName.equals(name)) {
425	                    return pet;
426	                }
427	            }
428	        }
429	        return null;
430	    }
431	
432	    public Pet getPet(Integer petId) {
433	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
434	    }
435	
436	    @Override
437	    public String toString() {
438	        return new ToStringCreator(this)
439	
440	            .append("id", this.getId())
441	            .append("new", this.isNew())
442	            .append("lastName", this.getLastName())
443	            .append("firstName", this.getFirstName())
444	            .append("address", this.address)
445	            .append("city", this.city)
446	            .append("telephone", this.telephone)
447	            .toString();
448	    }
449	}
