package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Flags the newly built owner as a possible (soft) duplicate of an existing one. A soft match is an
 * existing owner in the same household — same deterministic {@link Owner#getHouseholdId() householdId}
 * (last name and postcode) — but reachable on a different telephone. When one is found the earliest
 * such owner's id is recorded via {@link Owner#setPossibleDuplicateOf(Integer)}, which drives the
 * {@code possibleDuplicate} / {@code possibleDuplicateOf} response fields.
 *
 * <p>A {@link DeclaredHouseholdMember declared household member} — one admitted into an occupied
 * household via {@code sharesHousehold} — is deliberate, not suspected, so it is never flagged. Every
 * other same-household owner has already been rejected as a household duplicate by
 * {@link EnsureUniqueHousehold}. Owners without a postcode belong to no household and never soft-match.
 *
 * <p>Runs after {@link EnsureUniqueIdentity} and before {@link SaveOwner}, so the flag is persisted
 * with the owner.
 */
public class DetectPossibleDuplicate {

    public void service(@Val Owner owner, @Val DeclaredHouseholdMember declaredMember,
            OwnerRepository ownerRepository) {
        if (declaredMember != null) {
            return;
        }
        String householdId = owner.getHouseholdId();
        if (householdId == null || householdId.isBlank()) {
            return;
        }
        ownerRepository.findByLastName(owner.getLastName()).stream()
            .filter(existing -> householdId.equals(existing.getHouseholdId())
                && existing.getTelephone() != null
                && !existing.getTelephone().equals(owner.getTelephone()))
            .map(Owner::getId)
            .filter(id -> id != null)
            .min(Integer::compareTo)
            .ifPresent(owner::setPossibleDuplicateOf);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.util.List;
import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.model.Sha256;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.util.StringUtils;

/**
 * Household identity shared by the create-owner steps. A household is the set of owners with the same
 * last name (normalized case-insensitively with collapsed whitespace) and the same postcode. Its
 * {@code householdId} is derived deterministically from those two values, so any two owners with the
 * same last name and postcode share it automatically without an explicit link. Used by
 * {@link AssignHouseholdId} to stamp each owner, by {@link EnsureUniqueHousehold} to reject a second
 * owner in an occupied household, and by {@link CountHouseholdMembers} to size the household.
 */
final class Household {

    /** The number of leading hex characters of the SHA-256 digest that form a household id. */
    private static final int ID_LENGTH = 12;

    private Household() {
    }

    /** Case-insensitive form with leading/trailing and repeated inner whitespace collapsed to one space. */
    static String normalizeLastName(String lastName) {
        return lastName == null ? "" : lastName.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    /**
     * The deterministic household id for the given last name and postcode: the first
     * {@value #ID_LENGTH} hex characters of {@code SHA-256(normalizedLastName + '|' + postcode)}.
     * Returns {@code null} when no postcode is supplied, since a household is keyed on postcode and an
     * owner without one belongs to no household.
     */
    static String idFor(String lastName, String postcode) {
        if (!StringUtils.hasText(postcode)) {
            return null;
        }
        return Sha256.hex(normalizeLastName(lastName) + '|' + postcode).substring(0, ID_LENGTH);
    }

    /**
     * The existing owners sharing the given owner's household, i.e. those already persisted with the
     * same {@link Owner#getHouseholdId() householdId}. The owner itself is not yet saved, so it never
     * appears. An owner belonging to no household (no id) has no existing members.
     */
    static List<Owner> existingMembers(Owner owner, OwnerRepository ownerRepository) {
        String householdId = owner.getHouseholdId();
        if (householdId == null || householdId.isBlank()) {
            return List.of();
        }
        return ownerRepository.findByLastName(owner.getLastName()).stream()
            .filter(member -> householdId.equals(member.getHouseholdId()))
            .toList();
    }
}

